Here's a concrete example of debouncing a function in JavaScript. Imagine a search input where you don't want to trigger an API call on every single keystroke, but rather after the user has paused typing for a short period.

```javascript
function debounce(func, delay) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}

const searchInput = document.getElementById('search');
const handleSearch = (query) => {
  console.log('Searching for:', query);
  // In a real app, this would make an API call
};

const debouncedSearch = debounce(handleSearch, 300); // Wait 300ms after user stops typing

searchInput.addEventListener('input', (event) => {
  debouncedSearch(event.target.value);
});
```

