    int data;
    struct StackNode* next;
} StackNode;

StackNode* top = NULL;

void push(int data) {
    StackNode* newNode = (StackNode*)malloc(sizeof(StackNode));
    newNode->data = data;
    newNode->next = top;
    top = newNode;
}

int pop() {
    if (top == NULL) {
        printf("Stack is empty\n");
        return -1; // Ou une autre valeur d'erreur
    }
    int poppedData = top->data;
    StackNode* temp = top;
    top = top->next;
    free(temp);
    return poppedData;
}

